"""Apply appearance through native Voltron APIs; colors are managed hex strings."""
from native_hooks import h
def handlers(b):
 g,p,sv,t=b.get,b.put,b.set,b.text
 s='cmp w20,#0\nb.lt finish\ncmp w20,#8\nb.gt finish\nmov w26,w20\n'+h.load_game()+'\nldr x8,[x8,#0x28]\ncbz x8,finish\nldr x27,[x8,#0x80]\ncbz x27,finish\nmov x0,x27\nmov x1,xzr\nbl 0x2c9dfe8\nldr x28,[x27,#0x30]\ncbz x28,finish\n'+g('GeneticOriginalSaved')+'cbnz w24,gen_original_ready18\n'
 for feature,k in [(3,'OriginalSkin18'),(8,'OriginalHairColor18')]:s+=f'mov x0,x28\nmov w1,#{feature}\nmov x2,xzr\nbl 0x2f3e04c\ncbz x0,finish\n'+b.textptr(k,'x0')
 s+=sv('GeneticOriginalSaved',1)+'gen_original_ready18:\n'
 # A variation is a single selection; restore native colors before changing it.
 for feature,k in [(3,'OriginalSkin18'),(8,'OriginalHairColor18')]:s+=b.string(k)+f'mov x1,x0\nmov x0,x21\nmov x2,xzr\nmov x3,xzr\nbl 0x3059934\ncbz x0,finish\nmov x1,x0\nmov x0,x28\nmov w2,#{feature}\nmov x3,xzr\nbl 0x2f3e068\n'
 s+='mov x0,x28\nmov w1,#0\nmov w2,#3\nmov x3,xzr\nbl 0x2f3cda8\nbl 0x2f34138\ncbz x0,finish\nmov x25,x0\n'+b.string('eye')+'mov x1,x0\nmov x0,x25\nmov x2,xzr\nbl 0x2f50200\nmov w25,w0\ncmp w25,#0\nb.lt genetic_eye_reset_done18\nmov x0,x28\nmov w1,#0\nmov w2,w25\nmov x3,xzr\nbl 0x2f3cda8\ngenetic_eye_reset_done18:\ncmp w26,#1\nb.lt genetic_save18\ncmp w26,#3\nb.le genetic_base18\ncmp w26,#6\nb.eq genetic_dimples18\ncmp w26,#4\nb.eq genetic_albinism18\ncmp w26,#5\nb.eq genetic_eyes18\ncmp w26,#7\nb.eq genetic_curly18\nmov w24,#71\nb genetic_hair18\ngenetic_curly18:\nmov w24,#58\nb genetic_hair18\ngenetic_base18:\nmov w24,w26\nb genetic_set_base18\ngenetic_dimples18:\nmov w24,#4\ngenetic_set_base18:\nmov x0,x28\nmov w1,w24\nmov w2,#3\nmov x3,xzr\nbl 0x2f3cda8\nb genetic_save18\ngenetic_albinism18:\nbl 0x2f34138\ncbz x0,finish\nmov x23,x0\nmov w1,#0\nmov w2,#3\nmov x3,xzr\nbl 0x2f506e4\ncbz x0,finish\nmov x1,x0\nmov x0,x28\nmov w2,#3\nmov x3,xzr\nbl 0x2f3e068\nmov x0,x23\nmov w1,#0\nmov w2,#17\nmov x3,xzr\nbl 0x2f5062c\ncbz x0,finish\nmov x1,x0\nmov x0,x28\nmov w2,#8\nmov x3,xzr\nbl 0x2f3e068\nb genetic_save18\ngenetic_eyes18:\ncmp w25,#0\nb.lt genetic_save18\nmov x0,x28\nmov w1,#1\nmov w2,w25\nmov x3,xzr\nbl 0x2f3cda8\nb genetic_save18\ngenetic_hair18:\nmov x0,x28\nmov w1,w24\nmov w2,#8\nmov x3,xzr\nbl 0x2f3cda8\ngenetic_save18:\nmov x0,x27\nmov x1,xzr\nbl 0x2c9dfa4\nstr x0,[x27,#0x28]\nmov x0,x28\nmov w1,#0\nmov x2,xzr\nbl 0x2f4284c\nb finish\n'
 genius=h.load_game()+'\nldr x0,[x8,#0x28]\ncbz x0,finish\ncmp w20,#0\nb.le finish\ncmp w20,#3\nb.gt finish\nmov w1,w20\nmov x2,xzr\nbl 0x2a83d1c\nb finish\n'
 return [('NativeGeneticApply','life_v18','genetics18',s),('NativeGenius','life_v18','genius18',genius)]
